using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Runtime.InteropServices;
using System.Threading;

namespace ClearSpace {
public static class BetaTests {
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool CreateHardLink(string name,string existing,IntPtr security);
 static Finding Manual(Finding f){return new Finding{Rule=f.Rule,ManualOverride=true,Candidates=f.ManualCandidates.ToList(),EligibleBytes=f.ManualBytes};}
 public static int Run(string output){Directory.CreateDirectory(output);var tests=new List<string>();Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception("FAILED: "+label);tests.Add("PASS: "+label);};string fixture=Path.Combine(Path.GetFullPath(output),"beta-fixture-"+Guid.NewGuid().ToString("N")),cache=Path.Combine(fixture,"UnknownApp","Cache");Directory.CreateDirectory(cache);
  Action<string,string,int> write=(relative,contents,days)=>{string p=Path.Combine(cache,relative);Directory.CreateDirectory(Path.GetDirectoryName(p));File.WriteAllText(p,contents);File.SetLastWriteTimeUtc(p,DateTime.UtcNow.AddDays(-days).AddMinutes(-2));};
  try{
   write("index","cache index",10);write("data_0","cache block",10);write("blob.bin","binary data",10);write("nested\\resource.dat","nested resource",10);write("image.dat","%PDF cached personal fixture",10);write("settings.json","{\"fixture\":true}",10);write("recent.bin","recent cache",0);write("User\\accounts.dat","account fixture",10);
   var rule=HeuristicScanner.CacheRule("beta-unknown",cache,"Fixture Unknown",new string[0]);var engine=new Engine(new List<Rule>{rule}){FileBackupDirectory=Path.Combine(fixture,"backups")};var finding=engine.Scan(CancellationToken.None,null).Single();
   check(finding.Files==8&&finding.TotalBytes==Directory.GetFiles(cache,"*",SearchOption.AllDirectories).Sum(p=>new FileInfo(p).Length),"Unknown cache directories read all files and report the full content size");
   check(finding.Candidates.Count==4&&finding.Candidates.Any(p=>Path.GetFileName(p.Path)=="index")&&finding.Candidates.Any(p=>p.Path.EndsWith("blob.bin")),"Unknown cache enumeration includes extensionless, binary and nested content");
   check(finding.ManualCandidates.Count==4&&finding.ManualCandidates.Any(p=>p.Path.EndsWith("settings.json"))&&finding.ManualCandidates.Any(p=>p.Path.EndsWith("recent.bin")),"Recent and personal files are exposed as separate manual risk candidates");
   check(!rule.Quick&&rule.AllowManual&&engine.Clean(new[]{finding,Manual(finding)},true,CancellationToken.None,null).Deleted==0,"Unknown and retained candidates cannot enter one-click cleanup");
   var manual=Manual(finding);check(RiskConfirmation.Describe(new[]{manual},false).Contains("账号登录")&&RiskConfirmation.Describe(new[]{manual},false).Contains(cache),"Risk descriptions identify override effects and the actual directory");
   var result=engine.Clean(new[]{manual},false,CancellationToken.None,null);check(result.Deleted==4&&result.BackupFiles==4&&File.Exists(result.FileBackupManifest),"Manual cleanup deletes retained unknown-cache contents only after durable backups");check(File.Exists(Path.Combine(cache,"index"))&&FileRecovery.Restore(result.FileBackupManifest)==4,"Manual cleanup preserves unselected candidates and can restore exact originals");
   var original=engine.Clean(new[]{finding},false,CancellationToken.None,null);check(original.Deleted==4&&original.BackupFiles==4,"Normal unknown-cache candidates are selectable and always backed up");check(FileRecovery.Restore(original.FileBackupManifest)==4,"Extensionless and binary cache files restore successfully");
   string retainedDirectory=Path.Combine(fixture,"retained");Directory.CreateDirectory(retainedDirectory);string retainedFile=Path.Combine(retainedDirectory,"settings.json");File.WriteAllText(retainedFile,"retained fixture");File.SetLastWriteTimeUtc(retainedFile,DateTime.UtcNow.AddMinutes(-2));
   var retainedRule=new Rule("beta-retained","Retained","保留项目","","",new[]{retainedDirectory},30,false){Protected=true,AllowManual=true};engine=new Engine(new List<Rule>{retainedRule}){FileBackupDirectory=Path.Combine(fixture,"retained-backups")};finding=engine.ScanRule(retainedRule,CancellationToken.None);check(finding.Candidates.Count==0&&finding.ManualCandidates.Count==1,"A protected file rule exposes a separate opt-in deletion candidate");check(engine.Clean(new[]{finding},false,CancellationToken.None,null).Deleted==0,"An ordinary finding cannot silently remove protected files");manual=Manual(finding);check(engine.Clean(new[]{manual},true,CancellationToken.None,null).Deleted==0,"Even forged one-click selection cannot override retention");result=engine.Clean(new[]{manual},false,CancellationToken.None,null);check(result.Deleted==1&&result.BackupFiles==1&&FileRecovery.Restore(result.FileBackupManifest)==1,"Advanced protected-file cleanup forces backup in permanent mode");
   finding=engine.ScanRule(retainedRule,CancellationToken.None);manual=Manual(finding);File.AppendAllText(retainedFile," changed");result=engine.Clean(new[]{manual},false,CancellationToken.None,null);check(result.Deleted==0&&result.Skipped==1&&File.Exists(retainedFile),"Risk deletion still rejects files changed after scanning");
   File.SetLastWriteTimeUtc(retainedFile,DateTime.UtcNow.AddMinutes(-2));finding=engine.ScanRule(retainedRule,CancellationToken.None);manual=Manual(finding);using(var held=new FileStream(retainedFile,FileMode.Open,FileAccess.Read,FileShare.Read)){result=engine.Clean(new[]{manual},false,CancellationToken.None,null);check(result.Deleted==0&&result.Skipped==1,"Risk deletion does not remove occupied files");}
   retainedRule.Processes=new[]{"fixture-owner"};engine.IsRunning=owners=>true;finding=engine.ScanRule(retainedRule,CancellationToken.None);check(finding.Running&&finding.Candidates.Count==0&&finding.ManualCandidates.Count==0,"An active software owner blocks both normal and manual cache candidates");engine.IsRunning=owners=>false;finding=engine.ScanRule(retainedRule,CancellationToken.None);manual=Manual(finding);engine.IsRunning=owners=>true;result=engine.Clean(new[]{manual},false,CancellationToken.None,null);check(result.Deleted==0&&File.Exists(retainedFile),"An owner started after scanning also blocks risk deletion");engine.IsRunning=owners=>false;
   retainedRule.ExcludedRoots=new[]{retainedDirectory};finding=engine.ScanRule(retainedRule,CancellationToken.None);check(finding.ManualCandidates.Count==0,"Explicit excluded roots cannot be overridden by manual cleanup");retainedRule.ExcludedRoots=null;
   finding=engine.ScanRule(retainedRule,CancellationToken.None);manual=Manual(finding);string sibling=Path.Combine(fixture,"retained-neighbor");Directory.CreateDirectory(sibling);string outside=Path.Combine(sibling,"settings.json");File.WriteAllText(outside,"outside");manual.Candidates[0].Path=outside;result=engine.Clean(new[]{manual},false,CancellationToken.None,null);check(result.Deleted==0&&File.Exists(outside),"Manual cleanup remains bounded to its original rule roots");
   finding=engine.ScanRule(retainedRule,CancellationToken.None);manual=Manual(finding);check(CreateHardLink(Path.Combine(fixture,"shared-link.json"),retainedFile,IntPtr.Zero),"A hardlink fixture is created for manual-deletion boundary checks");result=engine.Clean(new[]{manual},false,CancellationToken.None,null);check(result.Deleted==0&&File.Exists(retainedFile),"Manual deletion refuses shared files even if a hardlink appears after scanning");
   var env=new Winapp2Environment{Drive=Path.GetPathRoot(fixture),AllowedBases=new[]{fixture},DeniedBases=new string[0],OSVersion=new Version(10,0,19045)};env.Variables["LocalAppData"]=new[]{fixture};string community="; Version: 260915\n[Saved Passwords *]\nDetectFile=%LocalAppData%\\UnknownApp\nFileKey1=%LocalAppData%\\UnknownApp\\Cache|*.json;*.dat|RECURSE\nExcludeKey1=FILE|%LocalAppData%\\UnknownApp\\Cache|settings.json\nWarning=Removing these may sign you out\n";
   var resolved=Winapp2Adapter.Resolve(Winapp2Parser.Parse(community),new DiscoveryResult(),env,CancellationToken.None,null);check(resolved.Any(r=>r.Protected&&r.AllowManual)&&resolved.All(r=>!r.Quick),"Known personal Winapp2 file scopes expose opt-in risk deletion without joining one-click");var communityEngine=new Engine(resolved){FileBackupDirectory=Path.Combine(fixture,"community-backups")};var communityFinding=communityEngine.Scan(CancellationToken.None,null).Single(f=>f.Rule.AllowManual);check(communityFinding.ManualCandidates.Count>0&&!communityFinding.ManualCandidates.Any(s=>s.Path.EndsWith("settings.json")),"Winapp2 exclusions are retained even for a risk deletion option");
   var bad=Winapp2Adapter.Resolve(Winapp2Parser.Parse(community+"MysteryAction=delete\n"),new DiscoveryResult(),env,CancellationToken.None,null);check(!bad.Any(r=>r.AllowManual),"Unsupported community directives do not gain a risk deletion bypass");
   var systemRule=SystemDiskCleanup.CreateRule();var system=new Finding{Rule=systemRule,VirtualItems=1};var systemEngine=new Engine(new List<Rule>{systemRule});int runs=0;systemEngine.RunSystemCleanup=(token,status)=>{runs++;status("Fixture only");return new SystemCleanupResult{Completed=true,Message="Fixture finished"};};check(systemEngine.Clean(new[]{system},true,CancellationToken.None,null).SystemCleanupStarted==false&&runs==0,"System disk cleanup is excluded from one-click mode");check(!systemEngine.Clean(new Finding[0],false,CancellationToken.None,null).SystemCleanupStarted&&runs==0,"An unselected system cleanup project never runs");result=systemEngine.Clean(new[]{system},false,CancellationToken.None,null);check(runs==1&&result.SystemCleanupStarted&&result.SystemCleanupCompleted&&result.EstimatedFreedBytes==0,"Selected system cleanup completion is logged without inventing scanned bytes");
   using(var cancelled=new CancellationTokenSource()){cancelled.Cancel();result=systemEngine.Clean(new[]{system},false,cancelled.Token,null);check(runs==1&&result.Cancelled,"Cancellation before system startup prevents its execution");}
   check(SystemDiskCleanup.Arguments=="/d C /verylowdisk"&&!SystemDiskCleanup.Arguments.Contains("sagerun"),"Automatic system cleanup targets only C using documented prompt-free arguments");check(RiskConfirmation.ItemText(system).Contains("无法在本工具中恢复"),"System cleanup confirmation states that Windows deletions bypass file recovery");
   var many=Enumerable.Range(0,35).Select(i=>new Finding{Rule=new Rule("r"+i,"Selected "+i,"软件缓存","","Risk "+i,new string[0],0,false)}).ToList();string descriptions=RiskConfirmation.Describe(many,true);check(many.All(f=>descriptions.Contains(f.Rule.Impact)),"Every selected project's risk is included without truncating the list");
   var safe=new Finding{Rule=new Rule("safe-fixture","Safe-only fixture","软件缓存","","Rebuildable cache",new string[0],0,true)};var mixed=new[]{safe,many[0]};check(RiskConfirmation.Required(mixed)&&!RiskConfirmation.Describe(mixed,true).Contains("Safe-only fixture")&&RiskConfirmation.Describe(mixed,true).Contains("Selected 0")&&mixed.Length==2,"Mixed cleanup confirms only risky projects without changing the original cleanup selection");
   var assembly=Assembly.GetExecutingAssembly();string info=assembly.GetCustomAttributes(typeof(AssemblyInformationalVersionAttribute),false).Cast<AssemblyInformationalVersionAttribute>().Single().InformationalVersion;var numeric=assembly.GetName().Version;bool beta=ReleaseVersion.IsBeta;string expected=beta?"beta0."+numeric.Minor.ToString("00"):numeric.Major+"."+numeric.Minor+"."+numeric.Build;check(ReleaseVersion.Display==expected&&beta==(numeric.Major==0)&&info==ReleaseVersion.FullVersion&&(beta?numeric.Revision==0&&numeric.Build==ReleaseVersion.Build:numeric.Revision==ReleaseVersion.Build),"Release labels, channels, internal builds and numeric file versions share one version definition");
   SoftwareUpdateTests.Verify(fixture,check);CleanupEnhancementTests.Verify(check);
   var baseline=RuleBook.Create();check(baseline.Where(r=>r.Id.StartsWith("system-")||r.InfoKind=="storage").All(r=>!r.AllowManual),"Core system files and Windows-managed directories cannot be manually removed by raw file deletion");
   File.WriteAllLines(Path.Combine(output,"beta-test-results.txt"),tests.Concat(new[]{"ALL "+tests.Count+" BETA CHECKS PASSED"}));return 0;
  }catch(Exception ex){File.WriteAllText(Path.Combine(output,"beta-test-results.txt"),String.Join("\n",tests)+"\n"+ex);return 1;}
 }
}
}
